                ll=ll[1:]
        source=None
        if cur in existing:source=cur
        elif p['wildcard']!='off':
            ce=labels(cur)[1:]
            while nm(ce) not in existing:ce=ce[1:]
            if p['wildcard']=='rfc' or len(labels(cur))==len(ce)+1:
                w=('*',)+ce
                if nm(w) in existing:source=nm(w)
        if source is None:return finish(cur,trace,ans,'NXDOMAIN','NXDOMAIN')
        rr=[r for r in z['records'] if r['owner'].lower()==source]
