def finish(cur,trace,ans,rcode,term):
    return {'rcode':rcode,'termination':term,'final_name':cur,
            'answer':[{'owner':o,'type':t,'data':d} for o,t,d in ans], 'trace':trace},(rcode,frozenset(ans))

def brute_diag(doc,sigs):
    ps=sorted(p['id'] for p in doc['profiles']);qs=sorted(doc['queries'],key=lambda q:q['id'])
    vec={p:tuple(sigs[q['id'],p] for q in qs) for p in ps}
    groups={}
    for p in ps:groups.setdefault(vec[p],[]).append(p)
    classes=sorted(groups.values())
    best=None
    for bits in range(1<<len(qs)):
        chosen=[qs[i] for i in range(len(qs)) if bits>>i&1]
        cost=sum(q['cost'] for q in chosen);cnt=len(chosen)
        if best is not None and (cost,cnt)>best[:2]:continue
        okay=True
        for a,b in itertools.combinations(ps,2):
            if vec[a]!=vec[b] and not any(sigs[q['id'],a]!=sigs[q['id'],b] for q in chosen):
                okay=False;break
        if okay and (best is None or (cost,cnt)<best[:2]):best=(cost,cnt,sorted(q['id'] for q in chosen))
    return {'equivalence':classes,'basis':best[2],'cost':best[0],'count':best[1]}

